import { inversifyContainer } from '../inversify/container';
import { userModel } from '../models/user';

export interface IContinueQueueItem {
    /** @returns any additional data to add to the continue request */
    preSend: () => unknown;
    /** called after receiving a response, before updating user and game data */
    preProcess?: () => (Promise<void> | void);
    /** called after recieving a response, after updating user and game data */
    postProcess?: () => (Promise<void> | void);
    onError?: (...params: unknown[]) => void;
}

export class ContinueQueue {
    public static queue: IContinueQueueItem[] = [];
    public static isQueueActive: boolean = false;

    public static enqueue(item: IContinueQueueItem): void {
        this.queue.push(item);
        if (this.isQueueActive === false) {
            this.isQueueActive = true;
            ContinueQueue.dequeue();
        }
    }

    public static async dequeue(): Promise<void> {
        const item = ContinueQueue.queue.shift();
        if (item) {
            try {
                const continueData = await item.preSend();
                const response = await inversifyContainer.gameServer.continueRequest(continueData);
                if (item.preProcess) { await item.preProcess(); }

                userModel.setData(response.PlayerData, response.RequestType, false, response.SessionStatus);
                inversifyContainer.gameModel.setData(response);

                if (item.postProcess) { await item.postProcess(); }

                if (this.queue.length > 0) {
                    ContinueQueue.dequeue();
                } else {
                    ContinueQueue.isQueueActive = false;
                }
            } catch (err) {
                console.error(err);
                if (item.onError) {
                    item.onError(err);
                }
                this.emptyQueue(err);
            }
        }
    }

    private static emptyQueue(err: unknown): void{
        ContinueQueue.isQueueActive = false;
        let queueItem = ContinueQueue.queue.shift();
        while (queueItem !== undefined) {
            if (queueItem.onError) {
                queueItem.onError(err);
            }
            queueItem = ContinueQueue.queue.shift();
        }
    }
}
